+        body: Bytes,
+        engine_rid: Option<&str>,
+        load_guards: LoadGuards,
+        metrics: &DispatchMetrics,
+        expiration: CancellationToken,
+        stream_abort: CancellationToken,
+    ) -> impl Future<Output = Result<Response<Body>, ApiError>> + Send {
