+async fn collect<T>(
+    replies: Result<tonic::Response<tonic::Streaming<T>>, Status>,
+) -> Result<Vec<T>, Status> {
+    replies?
+        .into_inner()
+        .collect::<Vec<_>>()
+        .await
+        .into_iter()
+        .collect()
